package lab.stridelab;
import android.Manifest;import android.app.Activity;import android.os.Bundle;import android.os.Handler;import android.os.Looper;import android.content.Intent;import android.content.Context;import android.content.pm.PackageManager;import android.location.Location;import android.location.LocationManager;import android.location.LocationListener;import android.webkit.*;import android.util.Base64;import android.widget.Toast;import android.view.View;import android.view.WindowInsets;import android.os.Build;import java.io.OutputStream;import java.util.Locale;
public class MainActivity extends Activity {
 private byte[] pending;private WebView view;private LocationManager lm;private LocationListener listener;private final Handler handler=new Handler(Looper.getMainLooper());
 @Override public void onCreate(Bundle state){super.onCreate(state);view=new WebView(this);setContentView(view);if(Build.VERSION.SDK_INT>=35){view.setOnApplyWindowInsetsListener((v,insets)->{android.graphics.Insets b=insets.getInsets(WindowInsets.Type.systemBars());v.setPadding(b.left,b.top,b.right,b.bottom);return insets;});} WebSettings settings=view.getSettings();settings.setJavaScriptEnabled(true);settings.setDomStorageEnabled(true);settings.setAllowFileAccess(false);settings.setAllowContentAccess(false);settings.setAllowFileAccessFromFileURLs(false);settings.setAllowUniversalAccessFromFileURLs(false);settings.setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);settings.setUserAgentString(settings.getUserAgentString()+" StrideLab/0.1.0 (reference-map)");view.setWebViewClient(new WebViewClient(){@Override public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest r){return !r.getUrl().toString().startsWith("file:///android_asset/");}});view.addJavascriptInterface(new Bridge(),"StrideAndroid");view.loadUrl("file:///android_asset/index.html");}
 public final class Bridge { @JavascriptInterface public void save(String name,String mime,String data){runOnUiThread(()->{try{if(pending!=null){toast("请先完成当前导出");return;}if(data.length()>40000000)throw new Exception("文件过大");pending=Base64.decode(data,Base64.DEFAULT);Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType(mime);i.putExtra(Intent.EXTRA_TITLE,name.replaceAll("[/\\\\]","_"));startActivityForResult(i,101);}catch(Exception e){pending=null;toast("无法开始导出");}});} @JavascriptInterface public void locate(){runOnUiThread(()->{if(checkSelfPermission(Manifest.permission.ACCESS_FINE_LOCATION)!=PackageManager.PERMISSION_GRANTED&&checkSelfPermission(Manifest.permission.ACCESS_COARSE_LOCATION)!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{Manifest.permission.ACCESS_FINE_LOCATION,Manifest.permission.ACCESS_COARSE_LOCATION},102);}else requestLocation();});} }
 private void toast(String s){Toast.makeText(this,s,Toast.LENGTH_SHORT).show();}
 private void cancelLocation(){if(lm!=null&&listener!=null)try{lm.removeUpdates(listener);}catch(Exception ignored){}listener=null;}
 private void locationError(){cancelLocation();view.evaluateJavascript("window.StrideMapLocationError&&window.StrideMapLocationError()",null);}
 private void locationResult(Location l){cancelLocation();view.evaluateJavascript(String.format(Locale.US,"window.StrideMapLocation&&window.StrideMapLocation(%.8f,%.8f)",l.getLatitude(),l.getLongitude()),null);}
 @SuppressWarnings("MissingPermission") private void requestLocation(){cancelLocation();try{lm=(LocationManager)getSystemService(Context.LOCATION_SERVICE);boolean fine=checkSelfPermission(Manifest.permission.ACCESS_FINE_LOCATION)==PackageManager.PERMISSION_GRANTED;String provider=fine&&lm.isProviderEnabled(LocationManager.GPS_PROVIDER)?LocationManager.GPS_PROVIDER:LocationManager.NETWORK_PROVIDER;if(!lm.isProviderEnabled(provider)){locationError();return;}Location last=lm.getLastKnownLocation(provider);if(last!=null&&System.currentTimeMillis()-last.getTime()<120000){locationResult(last);return;}listener=new LocationListener(){public void onLocationChanged(Location l){locationResult(l);}public void onProviderEnabled(String p){}public void onProviderDisabled(String p){locationError();}public void onStatusChanged(String p,int s,Bundle e){}};final LocationListener req=listener;lm.requestLocationUpdates(provider,1000,0,listener,Looper.getMainLooper());handler.postDelayed(()->{if(listener==req)locationError();},15000);}catch(Exception e){locationError();}}
 @Override public void onRequestPermissionsResult(int request,String[] permissions,int[] results){super.onRequestPermissionsResult(request,permissions,results);if(request==102){if(checkSelfPermission(Manifest.permission.ACCESS_FINE_LOCATION)==PackageManager.PERMISSION_GRANTED||checkSelfPermission(Manifest.permission.ACCESS_COARSE_LOCATION)==PackageManager.PERMISSION_GRANTED)requestLocation();else locationError();}}
 @Override protected void onActivityResult(int req,int result,Intent data){super.onActivityResult(req,result,data);if(req!=101)return;try{if(result==RESULT_OK&&data!=null&&pending!=null){try(OutputStream out=getContentResolver().openOutputStream(data.getData())){if(out==null)throw new Exception("No stream");out.write(pending);}toast("已保存");}}catch(Exception e){toast("保存失败");}finally{pending=null;}}
 @Override protected void onStop(){cancelLocation();super.onStop();} @Override protected void onDestroy(){cancelLocation();handler.removeCallbacksAndMessages(null);if(view!=null){view.removeJavascriptInterface("StrideAndroid");view.destroy();}super.onDestroy();}
}
